Translate the following GNU C++17 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define ff first
#define ss second
#define fastio ios_base::sync_with_stdio(0); cin.tie(0)
typedef long long ll;
typedef long double ld;
const ld pi = 3.141592654;
const ll N = 1000500;
const ll mod = 1000000007;
using namespace std;

ll cycle_size[N];
ll visited_nodes[N];
ll aggregate[N];

ll get_cycle_length(ll start, ll k, ll n){
	ll count = 0;
	while(true){
		if(visited_nodes[start]) break;
		visited_nodes[start] = true;
		start = (start * k) % n;
		count++;
	}
	return count;
}

ll power_mod(ll base, ll exponent){
	if(exponent == 0) return 1;
	ll half = power_mod(base, exponent / 2);
	if(exponent % 2 == 0) return (half * half) % mod;
	else return (base * ((half * half) % mod)) % mod;
}

int main(){
	fastio;
	ll n, k;
	cin >> n >> k;

	if(k == 0){
		cout << power_mod(n, n - 1) << "\n";
		return 0;
	}

	for(ll i = 0; i < n; i++){
		if(!visited_nodes[i]){
			ll cycle_len = get_cycle_length(i, k, n);
			cycle_size[cycle_len]++;
		}
	}

	for(ll i = 1; i <= n; i++){
		for(ll j = i; j <= n; j += i){
			if(cycle_size[j] != 0) aggregate[j] += cycle_size[i] * i;
		}
	}

	ll answer = 1;
	for(ll i = 1; i <= n; i++){
		if(aggregate[i] != 0) answer = (answer * power_mod(aggregate[i], cycle_size[i])) % mod;
	}

	cout << answer << "\n";
	return 0;
}
